"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def sublist_range(values, start_index, end_index):
    result = []
    index = start_index
    while (index < end_index):
        result.append(values[index])
        index = (index + 1)
    return result

sentence = 'this is a sentence made up of'

startindex = 0

substrlen = 0

offset = 0

sentencelist = []

for character in sentence:
    sentencelist.append(character)

substrlist = []

substring = ''

loop = True

while loop:
    offset = (offset + 1)
    substring = sublist_range(sentencelist, startindex, offset)
    substrlist.append(substring)
    if (offset >= len(sentencelist)):
        startindex = (startindex + 1)
        offset = startindex
        if (startindex >= len(sentencelist)):
            startindex = 0
            substrlen = 0
            offset = 0
            loop = False

listindex = 0

loop = True

while loop:
    excl = set()
    duplicate = False
    for ch in substrlist[listindex]:
        if (ch in excl):
            duplicate = True
            break
        excl.add(ch)
    if duplicate:
        substrlist.pop(listindex)
    else:
        listindex = (listindex + 1)
    if (listindex >= len(substrlist)):
        loop = False

loop = True

index = 0

maxstrings = []

maxlength = 0

while loop:
    try:
        current = substrlist[index]
        currentlen = len(current)
        if (currentlen > maxlength):
            maxlength = currentlen
            maxstrings = [current]
        elif (currentlen == maxlength):
            maxstrings.append(current)
        index = (index + 1)
    except Exception:
        loop = False

print('The Longest Substrings Without Duplicate Characters Are:')

display_strings = []

for s in maxstrings:
    display_strings.append(''.join(s))

print(display_strings)
